package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the The Sun Pharaoh with its own model and texture. Generated by shadw-mod mob. */
public class SunPharaohRenderer extends MobRenderer<SunPharaoh, SunPharaohModel.State, SunPharaohModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/sun_pharaoh.png");

	public SunPharaohRenderer(EntityRendererProvider.Context context) {
		super(context, new SunPharaohModel(context.bakeLayer(SunPharaohModel.LAYER)), 0.9F);
	}

	@Override
	public SunPharaohModel.State createRenderState() {
		return new SunPharaohModel.State();
	}

	@Override
	public void extractRenderState(SunPharaoh entity, SunPharaohModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(SunPharaohModel.State state) {
		return TEXTURE;
	}
}
